#include "beatglass/library/analysis_commit.hpp"
namespace beatglass::library { library_detail::Publish publish_operation(library_detail::SqliteCache& cache,const std::string& id,const AnalysisOperation& op,std::stop_token stop){ if(id.empty()||!op.valid()) return library_detail::Publish::error; if(stop.stop_requested()) return library_detail::Publish::cancelled; auto verifier=[&]{return op.verify(stop).outcome==FileVerificationOutcome::match;}; CacheKey key{op.identity.content_hash,op.identity.engine_version,op.identity.configuration_id,op.identity.mode}; auto result = op.serialize(); if(stop.stop_requested()) return library_detail::Publish::cancelled; return cache.publish(id,key,std::move(result),stop,verifier); } }
